<?php declare(strict_types=1); namespace Annam; $title='Order '.$order['order_no']; $base='/checkout/complete/'.$reference.'/'; ?>
<section class="wrap php-store-section"><div class="php-white php-checkout"><h1><?= e($order['order_no']) ?></h1><p>Order: <strong><?= e(str_replace('_',' ',$order['status'])) ?></strong> · Payment: <strong><?= e($order['payment_status']) ?></strong></p><?php if(($intent['mode']??'')==='test'): ?><p class="php-preview">Razorpay test payment · No real payment or bill.</p><?php endif; ?><h2><?= money($order['total']) ?></h2><p><?= e($order['address']['recipient_name']??'') ?> · <?= e($order['address']['phone']??'') ?></p><p><?= e(implode(', ',array_filter(array_intersect_key($order['address'],array_flip(['line1','line2','landmark','city','pincode']))))) ?></p><?php foreach($order['items'] as $line): ?><p class="php-total"><span><?= e($line['quantity'].' × '.$line['name']) ?></span><strong><?= money($line['line_total']) ?></strong></p><?php endforeach; ?>
<?php if($invoice): ?><a class="btn btn-primary" href="<?= e($base.'bill/') ?>">View / print bill</a><?php endif; ?>
<?php if($intent&&!in_array($order['payment_status'],['paid','refunded'],true)&&$order['status']!=='cancelled'): ?>
<?php if($intent['provider_order_id']): ?><button class="btn btn-primary" id="pay-online" data-options="<?= e(json_encode(['key'=>$intent['key_id'],'order_id'=>$intent['provider_order_id'],'amount'=>(int)$intent['amount'],'currency'=>'INR','name'=>$store->name(),'prefill'=>['name'=>$order['address']['recipient_name']??'','contact'=>$order['address']['phone']??'','email'=>$order['address']['email']??'']])) ?>">Pay <?= money($order['total']) ?></button><form id="payment-verify" method="post" action="<?= e($base.'verify/') ?>"><?= csrf() ?><?php foreach(['razorpay_payment_id','razorpay_order_id','razorpay_signature'] as $key): ?><input type="hidden" name="<?= e($key) ?>"><?php endforeach; ?></form><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><script src="/assets/payment.js" defer></script>
<?php else: ?><form method="post" action="<?= e($base.'pay/') ?>"><?= csrf() ?><button class="btn btn-primary">Continue to payment</button></form><?php endif; ?>
<form method="post" action="<?= e($base.'status/') ?>"><?= csrf() ?><button class="btn">Check payment status</button></form>
<?php elseif($order['payment_status']!=='paid'&&$order['payment_mode']==='manual'): ?><p><?= nl2br(e($store->config['checkout_settings']['payment_instructions']??'Please contact the kitchen to arrange payment.')) ?></p><?php endif; ?><p>Keep this page in the same browser to view your order and bill.</p></div></section>

<?php if($charge??null): ?><section class="wrap php-white"><h2>Courier delivery</h2><p><?= e(Delivery::COURIER) ?></p><?php if($charge['dispatched_at']): ?><p><?= e($charge['courier_name'].' · '.$charge['tracking_number']) ?></p><p>Courier charge: <?= money($charge['amount']) ?> · <?= $charge['paid_at']?'Paid separately':'Payable separately' ?></p><?php if(!$charge['paid_at']&&getenv('PAYMENTS_ENABLED')==='1'&&!empty($store->config['checkout_settings']['courier_online_enabled'])): ?><?php if($courierIntent['provider_order_id']??''): ?><button class="btn btn-primary" id="pay-courier" data-options="<?= e(json_encode(['key'=>$courierIntent['key_id'],'order_id'=>$courierIntent['provider_order_id'],'amount'=>(int)$courierIntent['amount'],'currency'=>'INR','name'=>$store->name()])) ?>">Pay courier charge</button><form id="courier-verify" method="post" action="<?= e($base.'courier-verify/') ?>"><?= csrf() ?><?php foreach(['razorpay_payment_id','razorpay_order_id','razorpay_signature'] as $k): ?><input type="hidden" name="<?= e($k) ?>"><?php endforeach; ?></form><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><script src="/assets/courier-payment.js" defer></script><?php else: ?><form method="post" action="<?= e($base.'courier-pay/') ?>"><?= csrf() ?><button class="btn btn-primary">Pay separate courier charge</button></form><?php endif; endif; endif; ?></section><?php endif; ?>